INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33053$nota-0120$m33053$, $m33054$Training and Racing with a Power Meter.pdf$m33054$, $m33055$357$m33055$, $m33056$In this scenario, you can afford to push a little harder on the uphill section because you will get a chance to recover on the downhill... If it's a 3-minute hill, for example, then you know you can hold 115 percent of your FTP for that amount of time without cracking when you are fresh, so you could knock off, say, 5 to 10 percent of that and try for 105 percent of FTP.$m33056$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33057$nota-0120$m33057$, $m33058$Training and Racing with a Power Meter.pdf$m33058$, $m33059$357$m33059$, $m33060$when you have a hill that flattens out at the top, or plateaus, then you have to be very careful to maintain FTP or just above it on the uphill portion. As soon as you crest the hill, you will want to get back on the gas and get back up to speed... any time spent below FTP after the crest of the hill and on the flat will be time you are giving away to your competition.$m33060$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33061$nota-0120$m33061$, $m33062$nota-0048$m33062$, $m33063$pre-requisito$m33063$, $m33064$usa a referência de potência sustentável por duração (Níveis/Zonas de Coggan, nota-0048) como teto de esforço em subida$m33064$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33065$nota-0121$m33065$, $m33066$Training and Racing with a Power Meter.pdf$m33066$, $m33067$350$m33067$, $m33068$he realized that he was working at more than 500 watts; when he was in the 'recovery line,' he was still having to put out 400 watts. Doing some quick math and drawing on a keen understanding of his FTP, he realized that he was going to get dropped very quickly. He reasoned... that if he was just sitting in on the break and over his FTP, then his time in the break was limited. So he did what every good rider should do at a point like this: Sit on!$m33068$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33069$nota-0121$m33069$, $m33070$nota-0021$m33070$, $m33071$pre-requisito$m33071$, $m33072$usa a FTP (nota-0021) como limiar de decisão tática em tempo real durante uma fuga$m33072$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33073$nota-0131$m33073$, $m33074$Training and Racing with a Power Meter.pdf$m33074$, $m33075$380$m33075$, $m33076$we call this the 30-30-30 workout, because it involves 30 seconds at 150 percent of FTP, 30 seconds of coasting (0 percent of FTP), and 30 seconds of running. By extending the intervals from 15 to 30 seconds, we take the workout from Level 7 to Level 6... The 30-30-30 workout is done continuously for 10 minutes. Rest for 5 minutes between intervals, completing three to five 10-minute intervals, and then cool down.$m33076$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33077$nota-0131$m33077$, $m33078$Training and Racing with a Power Meter.pdf$m33078$, $m33079$381$m33079$, $m33080$cyclocross demands a strong FTP, so the traditional Level 4 FTP workouts are important... We recommend doing four efforts at FTP for 10 minutes each, or three for 15 minutes each, or two for 20 minutes each, in order to get in the needed threshold work in one of your workouts each week.$m33080$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33081$nota-0131$m33081$, $m33082$nota-0048$m33082$, $m33083$pre-requisito$m33083$, $m33084$usa os Níveis de Coggan (nota-0048) como base de intensidade (150% FTP = Nível 6/7)$m33084$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33085$nota-0131$m33085$, $m33086$nota-0130$m33086$, $m33087$complementa$m33087$, $m33088$treino desenhado especificamente para replicar o padrão de esforço característico do ciclocross (nota-0130)$m33088$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33089$nota-0137$m33089$, $m33090$Training and Racing with a Power Meter.pdf$m33090$, $m33091$391$m33091$, $m33092$the mountain-bike course is very seldom about drafting... pacing (holding back your effort in the beginning to conserve energy for the end) does not work the same way in these two specialties. The time trialing rule about not starting too hard, in order to conserve energy for the finish, does not apply.$m33092$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33093$nota-0137$m33093$, $m33094$Training and Racing with a Power Meter.pdf$m33094$, $m33095$391$m33095$, $m33096$The Allen effect occurs when a competitor accelerates through a slow section of a course, knowing that a much faster section is coming up. As the competitor reaches the faster section and increases his speed, a larger gap can be created between him and the competitors behind him... it can become impossible for the riders still climbing that hill to close the gap.$m33096$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33097$nota-0137$m33097$, $m33098$Training and Racing with a Power Meter.pdf$m33098$, $m33099$392$m33099$, $m33100$This gap initially begins as a distance gap, and it is true that the distances between riders can fluctuate while the time gap remains the same... in most forms of bicycle racing, it's the distance between riders that determines the winners. In any case, holding back your effort in the beginning of a mountain-bike race is rarely going to help you in the end.$m33100$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33101$nota-0137$m33101$, $m33102$nota-0118$m33102$, $m33103$contradiz$m33103$, $m33104$contradiz diretamente a regra de pacing de contrarrelógio de estrada (nota-0118, 'não comece forte demais') — em MTB de ultraresistência sem draft, a lógica de pacing se inverte$m33104$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33105$nota-0140$m33105$, $m33106$Training and Racing with a Power Meter.pdf$m33106$, $m33107$404$m33107$, $m33108$Refer back to Table 3.1 (p. 32) for additional detail on power-based training levels. In the workout tables that follow, RI describes the rest interval between efforts.$m33108$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33109$nota-0140$m33109$, $m33110$Training and Racing with a Power Meter.pdf$m33110$, $m33111$423$m33111$, $m33112$LEVEL 4: LACTATE THRESHOLD (91–105% OF FTP)$m33112$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33113$nota-0140$m33113$, $m33114$nota-0048$m33114$, $m33115$pre-requisito$m33115$, $m33116$o catálogo de treinos é inteiramente organizado pelos Níveis/Zonas de Coggan (nota-0048) já documentados$m33116$)
